function recordKick(db: Database, bugId: string, mode: KickMode, dossierPath: string, sha: string, outcome: string, session?: { column: 'target_session' | 'spawned_session'; value: string }) {
  const id = `kick:${bugId}:${Date.now()}`;
  if (session) {
    db.query(`INSERT INTO kick(id, bug_record, mode, ${session.column}, dossier_path, dossier_sha16, sent_at, outcome) VALUES (?,?,?,?,?,?,strftime('%s','now'),?)`)
      .run(id, bugId, mode, session.value, dossierPath, sha, outcome);
  } else {
    db.query(`INSERT INTO kick(id, bug_record, mode, dossier_path, dossier_sha16, sent_at, outcome) VALUES (?,?,?,?,?,strftime('%s','now'),?)`)
      .run(id, bugId, mode, dossierPath, sha, outcome);
  }
}

